#pragma once
#include <cstdint>
namespace ks{class SerialDirectTask final{public:enum class Kind{Noop,Write};enum class Stage{Hold,ReadStatus,TestReady,AdmitReady,WriteData,MaskStatus,WriteStatus,Restore,Finish,Complete};enum class Read{Status,Input};enum class Write{Data,Status};explicit SerialDirectTask(Kind k):kind_(k),stage_(k==Kind::Noop?Stage::Finish:Stage::Hold){}Kind kind()const{return kind_;}Stage stage()const{return stage_;}uint8_t status()const{return status_;}uint8_t data()const{return data_;}
template<class Clock>unsigned nextClocks(Clock&&clock)const{switch(stage_){case Stage::Hold:case Stage::Restore:return 11;case Stage::ReadStatus:return 4;case Stage::WriteData:return 3+clock(Write::Data);case Stage::WriteStatus:return 3+clock(Write::Status);case Stage::Finish:return 17;case Stage::Complete:return 0;default:return 3;}}
template<class Reader,class Writer,class Clock>unsigned advanceBefore(unsigned available,Reader&&read,Writer&&write,Clock&&clock){unsigned used=0;while(auto cost=nextClocks(clock)){if(cost>available-used)break;switch(stage_){case Stage::Hold:stage_=Stage::ReadStatus;break;case Stage::ReadStatus:status_=uint8_t(read(Read::Status));stage_=Stage::TestReady;break;case Stage::TestReady:stage_=Stage::AdmitReady;break;case Stage::AdmitReady:stage_=(status_&128)?Stage::WriteData:Stage::ReadStatus;break;case Stage::WriteData:data_=uint8_t(read(Read::Input));write(Write::Data,data_);stage_=Stage::MaskStatus;break;case Stage::MaskStatus:status_&=127;stage_=Stage::WriteStatus;break;case Stage::WriteStatus:write(Write::Status,status_);stage_=Stage::Restore;break;case Stage::Restore:stage_=Stage::Finish;break;case Stage::Finish:stage_=Stage::Complete;break;default:break;}used+=cost;}return used;}private:Kind kind_;Stage stage_;uint8_t status_=0,data_=0;};}
